ssh wmicluster -T -o BatchMode=yes -o ConnectTimeout=12 -o ConnectionAttempts=1 -o ServerAliveInterval=5 -o ServerAliveCountMax=2 -o StrictHostKeyChecking=yes 'python3 -c '\''import json,hashlib,time
from pathlib import Path
from datetime import datetime,timezone
root=Path("/home/bnaskrecki/latent")
runs=root/"artifacts/campaign6/runs"
cutoff=datetime.fromisoformat("2026-10-19T22:56:41+00:00").timestamp()
def stat(p):
 s=p.stat()
 return {"bytes":s.st_size,"mtime_utc":datetime.fromtimestamp(s.st_mtime,timezone.utc).isoformat(),"newer_than_inventory":s.st_mtime>cutoff}
def metadata(p):
 if not p.exists():return None
 s=p.stat()
 if s.st_size>8000000: return {"error":"metadata size ceiling",**stat(p)}
 b=p.read_bytes();o=json.loads(b)
 fields={k:v for k,v in o.items() if v is None or isinstance(v,(str,int,float,bool))}
 if p.name=="selection.json":
  proof=o.get("proof_selection") or {}
  fields["proof_selection"]={k:proof.get(k) for k in ("step","solved","selected","complete")}
 return {"file":p.name,"sha256":hashlib.sha256(b).hexdigest(),**stat(p),"fields":fields}
out={"observed_utc":datetime.now(timezone.utc).isoformat(),"inventory_cutoff_utc":"2026-10-19T22:56:41Z","scope":"metadata reads and checkpoint stat only; no model, checkpoint contents, scheduler, or uploads","campaign":metadata(root/"status/campaign6.json"),"runs":[]}
paths=sorted(p for p in runs.iterdir() if p.is_dir())
if len(paths)>60:raise RuntimeError("run count ceiling")
for p in paths:
 row={"run":p.name,"status":metadata(p/"status.json"),"selection":metadata(p/"selection.json"),"checkpoints":[]}
 for q in sorted(p.glob("*.pt")):
  row["checkpoints"].append({"name":q.name,**stat(q)})
 if p.name=="wmi-pro6000-c6-main-qwen_vanilla-s47":row["receipt"]=metadata(p/"receipt.json")
 out["runs"].append(row)
print(json.dumps(out,separators=(",",":")))
'\'''
